import{_ as e,H as t,f as l,i}from"./chunks/framework.DIv0Dgmf.js";const u=JSON.parse('{"title":"第八章：调试和错误处理","description":"学会让 Claude 帮你找 bug 和修复错误","frontmatter":{"title":"第八章：调试和错误处理","description":"学会让 Claude 帮你找 bug 和修复错误"},"headers":[],"relativePath":"guide/3-practical-workflows/08-debugging.md","filePath":"guide/3-practical-workflows/08-debugging.md"}'),d={name:"guide/3-practical-workflows/08-debugging.md"};function o(s,a,r,n,h,c){return t(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="第八章-调试和错误处理" tabindex="-1">第八章：调试和错误处理 <a class="header-anchor" href="#第八章-调试和错误处理" aria-label="Permalink to &quot;第八章：调试和错误处理&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会让 Claude 帮你找出 bug 并修复。</p></div><h2 id="把错误信息粘贴给-claude" tabindex="-1">把错误信息粘贴给 Claude <a class="header-anchor" href="#把错误信息粘贴给-claude" aria-label="Permalink to &quot;把错误信息粘贴给 Claude&quot;">​</a></h2><h3 id="_1-运行你的代码" tabindex="-1">1. 运行你的代码 <a class="header-anchor" href="#_1-运行你的代码" aria-label="Permalink to &quot;1. 运行你的代码&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.py</span></span></code></pre></div><h3 id="_2-复制错误信息" tabindex="-1">2. 复制错误信息 <a class="header-anchor" href="#_2-复制错误信息" aria-label="Permalink to &quot;2. 复制错误信息&quot;">​</a></h3><p>把完整的错误信息复制下来。</p><h3 id="_3-粘贴给-claude" tabindex="-1">3. 粘贴给 Claude <a class="header-anchor" href="#_3-粘贴给-claude" aria-label="Permalink to &quot;3. 粘贴给 Claude&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我看看这个错误：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴错误信息]</span></span></code></pre></div><p>Claude 会告诉你：</p><ul><li>错误是什么</li><li>哪一行出了问题</li><li>怎么修复</li></ul><h2 id="修复步骤" tabindex="-1">修复步骤 <a class="header-anchor" href="#修复步骤" aria-label="Permalink to &quot;修复步骤&quot;">​</a></h2><h3 id="claude-解释后" tabindex="-1">Claude 解释后 <a class="header-anchor" href="#claude-解释后" aria-label="Permalink to &quot;Claude 解释后&quot;">​</a></h3><p>让 Claude 直接修复：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我修复这个问题</span></span></code></pre></div><h3 id="运行确认" tabindex="-1">运行确认 <a class="header-anchor" href="#运行确认" aria-label="Permalink to &quot;运行确认&quot;">​</a></h3><p>修复后重新运行代码，确认错误消失了。</p><h2 id="常见-python-错误" tabindex="-1">常见 Python 错误 <a class="header-anchor" href="#常见-python-错误" aria-label="Permalink to &quot;常见 Python 错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>含义</th></tr></thead><tbody><tr><td><code>SyntaxError</code></td><td>语法错误，括号、引号没配对</td></tr><tr><td><code>NameError</code></td><td>变量名写错了</td></tr><tr><td><code>TypeError</code></td><td>类型不匹配</td></tr><tr><td><code>IndexError</code></td><td>数组索引超出范围</td></tr></tbody></table><h2 id="调试心态" tabindex="-1">调试心态 <a class="header-anchor" href="#调试心态" aria-label="Permalink to &quot;调试心态&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">提示</p><p>AI 辅助不是万能的。</p></div><p>Claude 可能：</p><ul><li>给出的修复方案不正确</li><li>没有找到真正的问题</li><li>修复一个 bug 引入了新的 bug</li></ul><p><strong>永远要先理解问题，再接受修复。</strong></p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>写过能运行的代码。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 同样的错误修完又出现？</strong></p><p>A: 可能需要从根本上重构，不只是表面修复。</p><p><strong>Q: Claude 修错了？</strong></p><p>A: 用 <code>/undo</code> 撤销，或手动回滚到之前的版本。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>故意写一个有 bug 的代码</li><li>让 Claude 帮你找出来并修复</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何让 Claude 帮你做代码审查。</p><p><a href="/claude-code-guide/guide/3-practical-workflows/09-code-review.html">👉 第九章：代码审查和优化</a></p>`,36)])])}const b=e(d,[["render",o]]);export{u as __pageData,b as default};
